package com.example.service

import com.example.model.DailyAnimeFormatters
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONArray
import org.json.JSONObject
import java.util.concurrent.TimeUnit
import kotlin.random.Random

/**
 * Represents a personal random anime recommendation generated by My Shuffle.
 * Fetched directly from AniList in batches with zero Supabase storage, zero persistent history,
 * and zero YouTube Data API usage.
 */
data class MyShuffleAnimeItem(
    val anilistId: Int,
    val title: String,
    val secondaryTitle: String = "",
    val rating100: Int,
    val coverImage: String,
    val bannerImage: String? = null,
    val episodes: Int? = null,
    val startDate: String? = null,
    val endDate: String? = null,
    val rawStatus: String? = null,
    val rawFormat: String? = null,
    val rawSeason: String? = null,
    val releaseYear: Int? = null,
    val durationMinutes: Int? = null,
    val rawSource: String? = null,
    val studios: List<String> = emptyList(),
    val countryOfOrigin: String? = null,
    val genres: List<String> = emptyList(),
    val description: String = ""
) {
    val rating10Text: String
        get() = String.format(java.util.Locale.US, "%.1f / 10", rating100 / 10.0)

    val statusLabel: String
        get() = DailyAnimeFormatters.formatAiringStatus(rawStatus)

    val formatLabel: String
        get() = DailyAnimeFormatters.formatFormat(rawFormat)

    val seasonLabel: String
        get() = DailyAnimeFormatters.formatSeason(rawSeason)

    val sourceLabel: String
        get() = DailyAnimeFormatters.formatSource(rawSource)

    val startDateLabel: String
        get() = DailyAnimeFormatters.formatIsoDate(startDate)

    val episodesLabel: String
        get() = if (episodes != null && episodes > 0) "$episodes eps" else "Unknown eps"

    val episodesCountLabel: String
        get() = if (episodes != null && episodes > 0) episodes.toString() else "Unknown"

    val releaseYearLabel: String
        get() = when {
            releaseYear != null && releaseYear > 0 -> releaseYear.toString()
            !startDate.isNullOrBlank() && startDate.length >= 4 -> startDate.take(4)
            else -> "Unknown"
        }

    val releaseDateOrYearLabel: String
        get() {
            val formattedStart = DailyAnimeFormatters.formatIsoDate(startDate)
            return when {
                formattedStart != "Unknown" -> formattedStart
                releaseYear != null && releaseYear > 0 -> releaseYear.toString()
                else -> "Unknown"
            }
        }

    val durationLabel: String
        get() = if (durationMinutes != null && durationMinutes > 0) "$durationMinutes min" else "Unknown"

    val studiosLabel: String
        get() = if (studios.isNotEmpty()) studios.joinToString(", ") else "Unknown"
}

/**
 * Lightweight, zero-storage AniList batch randomizer for My Shuffle.
 * - Uses AniList GraphQL API exclusively.
 * - Enforces rating >= 6.0 (averageScore >= 60).
 * - Excludes BL, GL, Yaoi, Yuri, Shounen Ai, Shoujo Ai, and missing genre/tag metadata.
 * - Preserves normal Romance anime.
 * - Never writes to or reads from Supabase, SharedPreferences, or Room.
 * - Never calls YouTube Data API or trailer endpoints.
 */
class MyShuffleService(
    private val httpClient: OkHttpClient = OkHttpClient.Builder()
        .connectTimeout(15, TimeUnit.SECONDS)
        .readTimeout(15, TimeUnit.SECONDS)
        .build()
) {
    private val jsonMediaType = "application/json; charset=utf-8".toMediaType()
    private val poolMutex = Mutex()
    private val batchPool = ArrayDeque<MyShuffleAnimeItem>()

    private val sortModes = listOf(
        "POPULARITY_DESC",
        "SCORE_DESC",
        "FAVOURITES_DESC",
        "TRENDING_DESC"
    )

    suspend fun nextRandomAnime(currentAnilistId: Int? = null): Result<MyShuffleAnimeItem> =
        withContext(Dispatchers.IO) {
            poolMutex.withLock {
                // Draw from temporary in-memory batch buffer if available
                val buffered = drawFromBufferLocked(currentAnilistId)
                if (buffered != null) {
                    return@withContext Result.success(buffered)
                }

                // Fetch a new randomized batch from AniList
                var lastError: Throwable? = null
                for (attempt in 0 until 4) {
                    val sortMode = sortModes[Random.nextInt(sortModes.size)]
                    val maxPage = if (attempt < 2) 28 else 12
                    val randomPage = Random.nextInt(1, maxPage + 1)

                    val batchResult = fetchEligibleAniListBatch(page = randomPage, perPage = 50, sort = sortMode)
                    batchResult.onSuccess { fetchedItems ->
                        if (fetchedItems.isNotEmpty()) {
                            val shuffled = fetchedItems.shuffled(Random.Default)
                            batchPool.clear()
                            batchPool.addAll(shuffled)
                        }
                    }.onFailure { err ->
                        lastError = err
                    }

                    val picked = drawFromBufferLocked(currentAnilistId)
                    if (picked != null) {
                        return@withContext Result.success(picked)
                    }
                }

                Result.failure(
                    lastError ?: IllegalStateException("Unable to shuffle anime from AniList right now. Please try again.")
                )
            }
        }

    private fun drawFromBufferLocked(currentAnilistId: Int?): MyShuffleAnimeItem? {
        if (batchPool.isEmpty()) return null
        if (batchPool.size == 1 && batchPool.first().anilistId == currentAnilistId) {
            batchPool.clear()
            return null
        }
        val first = batchPool.removeFirst()
        if (currentAnilistId != null && first.anilistId == currentAnilistId && batchPool.isNotEmpty()) {
            val second = batchPool.removeFirst()
            batchPool.addLast(first)
            return second
        }
        return first
    }

    private fun fetchEligibleAniListBatch(
        page: Int,
        perPage: Int,
        sort: String
    ): Result<List<MyShuffleAnimeItem>> {
        return runCatching {
            val query = """
                query (${'$'}page: Int!, ${'$'}perPage: Int!, ${'$'}sort: [MediaSort]) {
                  Page(page: ${'$'}page, perPage: ${'$'}perPage) {
                    media(
                      type: ANIME,
                      isAdult: false,
                      averageScore_greater: 59,
                      status_in: [FINISHED, RELEASING],
                      genre_not_in: ["Hentai", "Boys' Love", "Girls' Love", "Yaoi", "Yuri", "Shounen Ai", "Shoujo Ai"],
                      tag_not_in: ["Boys' Love", "Girls' Love", "Yuri", "Yaoi", "Shounen Ai", "Shoujo Ai"],
                      sort: ${'$'}sort
                    ) {
                      id
                      title { english romaji native }
                      coverImage { extraLarge large }
                      bannerImage
                      averageScore
                      episodes
                      startDate { year month day }
                      endDate { year month day }
                      status
                      format
                      season
                      seasonYear
                      genres
                      tags { name category }
                      description(asHtml: false)
                      duration
                      source
                      countryOfOrigin
                      studios(isMain: true) { nodes { name } }
                    }
                  }
                }
            """.trimIndent()

            val payload = JSONObject().apply {
                put("query", query)
                put(
                    "variables",
                    JSONObject().apply {
                        put("page", page)
                        put("perPage", perPage)
                        put("sort", JSONArray().put(sort).put("ID"))
                    }
                )
            }

            val req = Request.Builder()
                .url("https://graphql.anilist.co")
                .header("Content-Type", "application/json")
                .header("Accept", "application/json")
                .post(payload.toString().toRequestBody(jsonMediaType))
                .build()

            val mediaArray = httpClient.newCall(req).execute().use { resp ->
                if (!resp.isSuccessful) {
                    throw IllegalStateException("AniList returned HTTP ${resp.code}")
                }
                val bodyStr = resp.body?.string().orEmpty()
                JSONObject(bodyStr)
                    .optJSONObject("data")
                    ?.optJSONObject("Page")
                    ?.optJSONArray("media")
                    ?: JSONArray()
            }

            val eligibleList = mutableListOf<MyShuffleAnimeItem>()
            for (i in 0 until mediaArray.length()) {
                val m = mediaArray.optJSONObject(i) ?: continue
                val parsed = parseAndValidateCandidate(m) ?: continue
                eligibleList.add(parsed)
            }
            eligibleList
        }
    }

    private fun parseAndValidateCandidate(m: JSONObject): MyShuffleAnimeItem? {
        val id = m.optInt("id", 0)
        val score = m.optInt("averageScore", 0)
        if (id <= 0 || score < 60 || score > 100) return null

        val titleObj = m.optJSONObject("title")
        val english = titleObj?.optString("english")?.trim()?.takeIf { it.isNotBlank() && it != "null" }
        val romaji = titleObj?.optString("romaji")?.trim()?.takeIf { it.isNotBlank() && it != "null" }
        val nativeTitle = titleObj?.optString("native")?.trim()?.takeIf { it.isNotBlank() && it != "null" }
        val displayTitle = english ?: romaji ?: nativeTitle ?: return null
        val secondaryTitle = when {
            !romaji.isNullOrBlank() && romaji != displayTitle -> romaji
            !nativeTitle.isNullOrBlank() && nativeTitle != displayTitle -> nativeTitle
            else -> ""
        }

        val coverObj = m.optJSONObject("coverImage")
        val cover = coverObj?.optString("extraLarge")?.trim()?.takeIf { it.isNotBlank() && it != "null" }
            ?: coverObj?.optString("large")?.trim()?.takeIf { it.isNotBlank() && it != "null" }
            ?: return null
        if (!cover.startsWith("http://", ignoreCase = true) && !cover.startsWith("https://", ignoreCase = true)) {
            return null
        }

        val genresArr = m.optJSONArray("genres")
        val genres = mutableListOf<String>()
        if (genresArr != null) {
            for (g in 0 until genresArr.length()) {
                val gName = genresArr.optString(g).trim()
                if (gName.isNotBlank() && gName != "null") {
                    genres.add(gName)
                }
            }
        }

        val tagsArr = m.optJSONArray("tags")
        val tags = mutableListOf<String>()
        if (tagsArr != null) {
            for (t in 0 until tagsArr.length()) {
                val tagObj = tagsArr.optJSONObject(t)
                if (tagObj != null) {
                    val tName = tagObj.optString("name").trim()
                    if (tName.isNotBlank() && tName != "null") {
                        tags.add(tName)
                    }
                    val tCategory = tagObj.optString("category").trim()
                    if (tCategory.isNotBlank() && tCategory != "null" &&
                        DailyAnimeFormatters.isExcludedBlGlToken(tCategory)
                    ) {
                        tags.add(tCategory)
                    }
                }
            }
        }

        // Strict BL / GL / Yaoi / Yuri exclusion & conservative missing genre/tag check
        // (Ordinary Romance anime without BL/GL genres or tags pass cleanly)
        if (DailyAnimeFormatters.hasExcludedBlGlGenreOrTag(genres, tags)) {
            return null
        }

        val studiosArr = m.optJSONObject("studios")?.optJSONArray("nodes")
        val studios = mutableListOf<String>()
        if (studiosArr != null) {
            for (s in 0 until studiosArr.length()) {
                val sName = studiosArr.optJSONObject(s)?.optString("name")?.trim().orEmpty()
                if (sName.isNotBlank() && sName != "null") {
                    studios.add(sName)
                }
            }
        }

        val startDateStr = formatFuzzyDateJson(m.optJSONObject("startDate"))
        val endDateStr = formatFuzzyDateJson(m.optJSONObject("endDate"))
        val seasonYear = m.optInt("seasonYear", 0).takeIf { it > 0 }
            ?: m.optJSONObject("startDate")?.optInt("year", 0)?.takeIf { it > 0 }

        val rawDesc = m.optString("description").takeIf { it != "null" }.orEmpty()
        val cleanDesc = rawDesc
            .replace(Regex("(?i)<br\\s*/?>"), "\n")
            .replace(Regex("<[^>]+>"), "")
            .replace("&quot;", "\"")
            .replace("&#39;", "'")
            .replace("&apos;", "'")
            .replace("&amp;", "&")
            .replace("&lt;", "<")
            .replace("&gt;", ">")
            .replace(Regex("\\n{3,}"), "\n\n")
            .trim()

        return MyShuffleAnimeItem(
            anilistId = id,
            title = displayTitle,
            secondaryTitle = secondaryTitle,
            rating100 = score,
            coverImage = cover,
            bannerImage = m.optString("bannerImage").trim().takeIf { it.isNotBlank() && it != "null" },
            episodes = m.optInt("episodes", 0).takeIf { it > 0 },
            startDate = startDateStr,
            endDate = endDateStr,
            rawStatus = m.optString("status").takeIf { it.isNotBlank() && it != "null" },
            rawFormat = m.optString("format").takeIf { it.isNotBlank() && it != "null" },
            rawSeason = m.optString("season").takeIf { it.isNotBlank() && it != "null" },
            releaseYear = seasonYear,
            durationMinutes = m.optInt("duration", 0).takeIf { it > 0 },
            rawSource = m.optString("source").takeIf { it.isNotBlank() && it != "null" },
            studios = studios,
            countryOfOrigin = m.optString("countryOfOrigin").takeIf { it.isNotBlank() && it != "null" },
            genres = genres,
            description = cleanDesc
        )
    }

    private fun formatFuzzyDateJson(obj: JSONObject?): String? {
        if (obj == null) return null
        val y = obj.optInt("year", 0)
        if (y <= 0) return null
        val m = obj.optInt("month", 0)
        val d = obj.optInt("day", 0)
        return when {
            m in 1..12 && d in 1..31 -> String.format(java.util.Locale.US, "%04d-%02d-%02d", y, m, d)
            m in 1..12 -> String.format(java.util.Locale.US, "%04d-%02d", y, m)
            else -> String.format(java.util.Locale.US, "%04d", y)
        }
    }
}
